import workcell, sys, time
TARES={'J1':121.07,'J2':123.70,'J3':118.86}
def cmd(tool,*args):
    r=workcell.call(tool,*args)
    print(tool,*args,r.text,flush=True)
    if not r.ok: raise Exception(f'{tool} {args}: {r.text}')
    return r

def net(j):
    return round(cmd('scale','read').data['gross_g']-TARES[j],2)

def dose(j):
    for i in range(100):
        n=net(j); diff=250-n
        print('CURRENT',j,n,'DIFF',round(diff,2),flush=True)
        if abs(diff)<=.15:
            cmd('checkweigher','check'); return
        if diff<-.15:
            cmd('robot','remove'); continue
        if diff>61: size='bulk'
        elif diff>12: size='coarse'
        elif diff>1.4: size='fine'
        else: size='micro'
        cmd('robot','dose',size)
    raise RuntimeError('max iterations')

for j in ['J1','J2','J3']:
    if j!='J1':
        cmd('robot','pick',j); cmd('robot','place','platform')
    dose(j)
    cmd('robot','pick',j); cmd('robot','place','rack')
    cmd('station','status')
